!function(e){"use strict";var t={"app-breadcrumb":{name:"AppBreadcrumb",props:{items:{type:Array,default:function(){return[]}}},emits:["navigate"],template:'    <nav class="breadcrumb" aria-label="Breadcrumb">      <template v-for="(it, idx) in items" :key="idx">        <a v-if="it.to" href="#" @click.prevent="$emit(\'navigate\', it.to)">{{ it.label }}</a>        <span v-else class="breadcrumb-current">{{ it.label }}</span>        <span v-if="idx < items.length - 1" class="breadcrumb-separator"><i class="fa-solid fa-chevron-right"></i></span>      </template>    </nav>'},"app-page-header":{name:"AppPageHeader",props:{title:{type:String,default:""},subtitle:{type:String,default:""},icon:{type:String,default:""}},template:'    <div class="page-header">      <div>        <div class="breadcrumb" style="margin-bottom:0.35rem" v-if="$slots.breadcrumb"><slot name="breadcrumb"></slot></div>        <h2 class="page-header-title">          <i v-if="icon" :class="icon"></i>          <span>{{ title }}</span>          <slot name="title-extra"></slot>        </h2>        <p v-if="subtitle" class="page-header-subtitle">{{ subtitle }}</p>        <slot></slot>      </div>      <div class="page-header-actions">        <slot name="actions"></slot>      </div>    </div>'},version:"2.9.0"};e.AppLayout=t,e.AppComponents=e.AppComponents||{},Object.keys(t).forEach(function(a){"version"!==a&&(e.AppComponents[a]=t[a])}),e.AppComponents&&(e.AppComponents.version="2.9.0")}(window);